class SimpleQueue {
  constructor() {
    this.items = [];
    this.head = 0;                 // index of the front item
  }
  enqueue(x) {
    this.items.push(x);            // join at the back
  }
  dequeue() {
    if (this.isEmpty()) return undefined;   // underflow: nobody is waiting
    const x = this.items[this.head];
    this.head++;                   // the next item becomes the front
    return x;
  }
  peek() {
    return this.isEmpty() ? undefined : this.items[this.head];
  }
  isEmpty() {
    return this.size() === 0;
  }
  size() {
    return this.items.length - this.head;
  }
}

from collections import deque

class SimpleQueue:
    def __init__(self):
        self.items = deque()

    def enqueue(self, x):
        self.items.append(x)          # join at the back

    def dequeue(self):
        if self.is_empty():
            return None               # underflow: nobody is waiting
        return self.items.popleft()   # leave from the front

    def peek(self):
        return self.items[0] if self.items else None

    def is_empty(self):
        return len(self.items) == 0

    def size(self):
        return len(self.items)

class SimpleQueue {
    private final ArrayDeque<Integer> items = new ArrayDeque<>();

    void enqueue(int x) {
        items.addLast(x);                // join at the back
    }

    Integer dequeue() {
        return items.pollFirst();        // leave from the front; null if empty
    }

    Integer peek() {
        return items.peekFirst();        // look at the front; null if empty
    }

    boolean isEmpty() {
        return items.isEmpty();
    }

    int size() {
        return items.size();
    }
}

