        items.push_back(x);              // join at the back
    }

    int dequeue() {
        if (isEmpty()) throw out_of_range("dequeue from an empty queue");   // underflow
        int x = items.front();           // remember the front
        items.pop_front();               // then remove it
        return x;
    }

    int peek() {
        if (isEmpty()) throw out_of_range("peek at an empty queue");
